<template><div class="page-container"><div class="page-header"><h2>仓储管理</h2><el-button type="primary" @click="showIn=true">入库</el-button><el-button type="warning" @click="showOut=true">出库</el-button></div><el-table :data="list" border stripe v-loading="loading"><el-table-column prop="productId" label="产品ID"/><el-table-column prop="batchId" label="批次ID"/><el-table-column prop="opType" label="类型" width="80"><template #default="{r}"><el-tag :type="r.opType==='in'?'success':'warning'" size="small">{{r.opType==='in'?'入库':'出库'}}</el-tag></template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="operator" label="操作人"/><el-table-column prop="createdAt" label="时间" width="160"/></el-table><el-dialog v-model="showIn" title="入库" width="400px"><el-form :model="form" label-width="60px"><el-form-item label="产品ID"><el-input-number v-model="form.productId" :min="1"/></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1"/></el-form-item><el-form-item label="操作人"><el-input v-model="form.operator"/></el-form-item></el-form><template #footer><el-button @click="showIn=false">取消</el-button><el-button type="primary" @click="handleIn">确认入库</el-button></template></el-dialog><el-dialog v-model="showOut" title="出库" width="400px"><el-form :model="form" label-width="60px"><el-form-item label="产品ID"><el-input-number v-model="form.productId" :min="1"/></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1"/></el-form-item><el-form-item label="操作人"><el-input v-model="form.operator"/></el-form-item></el-form><template #footer><el-button @click="showOut=false">取消</el-button><el-button type="warning" @click="handleOut">确认出库</el-button></template></el-dialog></div></template>
<script setup>import {ref,reactive,onMounted} from 'vue';import {supplyApi} from '@/api';import {ElMessage} from 'element-plus';const loading=ref(false),list=ref([]),showIn=ref(false),showOut=ref(false);const form=reactive({productId:1,quantity:1,orderId:0,operator:'',remark:''});onMounted(()=>loadData());async function loadData(){loading.value=true;try{const r=await supplyApi.getStockList({page:1,pageSize:100});list.value=r.data.list}catch(e){list.value=[]}finally{loading.value=false}}async function handleIn(){try{await supplyApi.warehouseIn(form);ElMessage.success('入库成功');showIn.value=false;loadData()}catch(e){}}async function handleOut(){try{await supplyApi.warehouseOut(form);ElMessage.success('出库成功');showOut.value=false;loadData()}catch(e){}}</script>
